<?php
require_once __DIR__.'/includes/bootstrap.php'; require_admin();
$notice=''; $error='';
if(is_post()){
 verify_csrf(); $action=$_POST['action']??''; $id=(int)($_POST['id']??0);
 try{
  if(!$db) throw new RuntimeException('Database unavailable.');
  if($action==='send'){
   if(!wdh_process_email($db,$id)) throw new RuntimeException('Email could not be sent by the server mail transport. The message remains logged.');
   $notice='Email sent successfully.';
  } elseif($action==='cancel'){
   $db->prepare("UPDATE email_queue SET status='cancelled' WHERE id=? AND status IN ('queued','failed')")->execute([$id]); $notice='Email cancelled.';
  } elseif($action==='retry'){
   $db->prepare("UPDATE email_queue SET status='queued',last_error=NULL WHERE id=? AND status='failed'")->execute([$id]); $notice='Email returned to the queue.';
  } else throw new RuntimeException('Invalid action.');
 }catch(Throwable $e){$error=$e->getMessage();}
}
$emails=$db?$db->query('SELECT * FROM email_queue ORDER BY id DESC LIMIT 100')->fetchAll():[];
$logs=$db?$db->query('SELECT c.*,u.full_name FROM communication_log c LEFT JOIN users u ON u.id=c.user_id ORDER BY c.id DESC LIMIT 50')->fetchAll():[];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Communications — WDH Admin</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="admin-page"><div class="portal-welcome"><div><span class="eyebrow mint">COMMUNICATIONS</span><h1>Email & Customer Updates</h1><p>Portal notifications are immediate; email messages are queued and can be sent when the server mail transport is configured.</p></div><a class="btn secondary" href="admin.php">Admin Dashboard</a></div><?php if($notice):?><div class="alert success-alert"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="admin-section"><div class="section-head"><span class="eyebrow mint">EMAIL QUEUE</span><h2>Outgoing Email</h2></div><div class="admin-table"><?php if(!$emails):?><div class="empty">No outgoing email messages.</div><?php else:foreach($emails as $r):?><div class="admin-row" style="display:block"><div style="display:flex;justify-content:space-between;gap:16px"><div><strong><?=e($r['subject'])?></strong><small><?=e($r['to_email'])?> · <?=e($r['email_type'])?></small></div><span class="badge"><?=e($r['status'])?></span></div><small>Created: <?=e($r['created_at'])?> · Attempts: <?=e($r['attempts'])?></small><?php if($r['last_error']):?><div class="alert error" style="margin-top:10px"><?=e($r['last_error'])?></div><?php endif;?><div class="actions" style="margin-top:10px"><?php if(in_array($r['status'],['queued','failed'],true)):?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn primary small" name="action" value="send">Send</button></form><?php endif;?><?php if($r['status']==='failed'):?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn secondary small" name="action" value="retry">Retry</button></form><?php endif;?><?php if(in_array($r['status'],['queued','failed'],true)):?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn secondary small" name="action" value="cancel">Cancel</button></form><?php endif;?></div></div><?php endforeach;endif;?></div></section><section class="admin-section"><div class="section-head"><span class="eyebrow mint">COMMUNICATION LOG</span><h2>Recent Customer Updates</h2></div><div class="admin-table"><?php if(!$logs):?><div class="empty">No communication activity yet.</div><?php else:foreach($logs as $r):?><div class="admin-row" style="display:block"><strong><?=e($r['subject']??'Customer update')?></strong><small><?=e($r['full_name']??'Customer')?> · <?=e($r['channel'])?> · <?=e($r['created_at'])?></small><p><?=nl2br(e($r['message']))?></p></div><?php endforeach;endif;?></div></section></main><?php require __DIR__.'/includes/footer.php';?></body></html>
